1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
4	
5	import { getLang, onChange } from '../i18n';
6	
7	export type ExChoice = 'glider' | 'guided';
8	
9	const el = () => document.getElementById('chooser');
10	
11	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
12	function lockGliderOnTouch(root: HTMLElement): void {
13	  if (!window.matchMedia('(hover: none)').matches) return;
14	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
15	  if (!card) return;
16	  card.disabled = true;
17	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
18	}
19	
20	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
21	function wireLang(root: HTMLElement): void {
22	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
23	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
24	  if (!mine || !main) return;
25	  mine.innerHTML = main.innerHTML; mine.value = getLang();
26	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
27	  onChange((code) => { mine.value = code; });
28	}
29	
30	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
31	const inerted: HTMLElement[] = [];
32	function setUnderInert(root: HTMLElement, on: boolean): void {
33	  if (on) {
34	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
35	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
36	      c.inert = true; inerted.push(c);
37	    }
38	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
39	}
40	
41	export function exShowChooser(onPick: (choice: ExChoice) => void): void {
42	  const root = el();
43	  if (!root) return;
44	  lockGliderOnTouch(root);
45	  wireLang(root);
46	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
47	    if (b.disabled) return;
48	    b.addEventListener('click', () => { exHideChooser(); onPick(b.dataset.pick as ExChoice); }, { once: true });
49	  });
50	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
51	  const loading = document.getElementById('loading');
52	  if (!loading || loading.classList.contains('done')) { show(); return; }
53	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
54	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
55	}
56	
57	export function exHideChooser(): void {
58	  const root = el();
59	  if (root) { root.hidden = true; setUnderInert(root, false); }
60	}
